import{_ as p,a0 as o,w as s,s as l,ao as d,I as u,x as e,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander | LCTT x X-CMD","titleTemplate":false,"description":"如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander","title":"如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander","tag":"201310","desc":""},"relativePath":"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander.md","filePath":"[post].md"}'),i={name:"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander.md"};function g(m,t,b,U,w,c){const n=o("Link");return s(),l("div",null,[t[14]||(t[14]=d(`<h1 id="如何從ubuntu13-04-升級到ubuntu13-10-saucy-salamander" tabindex="-1">如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander <a class="header-anchor" href="#如何從ubuntu13-04-升級到ubuntu13-10-saucy-salamander" aria-label="Permalink to “如何從Ubuntu13.04 升級到Ubuntu13.10 Saucy Salamander”">​</a></h1><p><strong>Ubuntu 13.10 Saucy</strong>已於<strong>10月17日</strong>發佈。希望它比Ubuntu 13.04 Raring版本或以前的版本有很大的改進及增加更多功能。大家都好奇地等着，想看看Ubuntu13.10將給Ubuntu愛好者帶來些什麼。</p><p>如果你的系統是Ubuntu的13.04、12.10、12.04 Precise Pangolin或者更早的版本的話，你願意升級到這最新的發行版本嗎？我知道你願意。只需要按照下面所示的簡單幾步，不管你用的是桌面版本還是服務器版本，都能輕鬆地從Ubuntu13.04版本升級到Ubuntu 13.10 Saucy版本。</p><p><strong>注意</strong>：在升級前，確保對你的 <strong>數據做一次全備份</strong>，備份存儲到外部設備（USB記憶棒或CD/ DVD）。</p><p>###桌面版升級</p><p>在升級前，我們首先得更新系統，按下快捷鍵打開終端輸入如下命令。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>然後就可以升級到最新的發行版本了。</p><pre><code>sudo update-manager -d
</code></pre><p>Software Updater將會打開並且搜索新的發佈版本。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Software-Updater_001.png" alt=""></p><p>幾秒鐘以後，你會看到如下所示，標有“<strong>However, Ubuntu 13.10 is available now (you have 13.04)</strong>”字樣的窗口。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Software-Updater_002.png" alt=""></p><p>然後點擊<strong>Upgrade</strong>按鈕。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Release-Notes_003.png" alt=""></p><p>Software Updater會讓你確認是否仍要升級。點擊<strong>Start Upgrade</strong>就真正開始安裝Ubuntu 13.10了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_005.png" alt=""></p><p>現在Software Updater就會獲取文件包並進行安裝。這將需要一段時間，具體時間長短取決於你的網絡連接速度。坐下來放鬆片刻吧。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Distribution-Upgrade_006.png" alt=""></p><p>過一會兒，你將被詢問是否刪除不必要的應用程序。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_008.png" alt=""></p><p>最後，點擊重啓完成升級。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_009.png" alt=""></p><p>現在你的系統就是最新的Ubuntu 13.10發佈版本了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Details_010.png" alt=""></p><p>###服務器版升級</p><p>要從Ubuntu 13.10服務器版升級到Ubuntu 13.04服務器版本，請按下面步驟操作。</p><p>如果還沒有安裝 <strong>update-manager-core</strong> 軟件包，請先安裝它：</p><pre><code>sudo apt-get install update-manager-core
</code></pre><p>打開 <strong>/etc/update-manager/release-upgrades</strong> 文件，</p><pre><code>sudo nano /etc/update-manager/release-upgrades
</code></pre><p>按如下所示進行編輯，設置 <strong>Prompt=normal</strong>。</p><pre><code># Default behavior for the release upgrader.

[DEFAULT]
# Default prompting behavior, valid options:
#
#  never  - Never check for a new release.
#  normal - Check to see if a new release is available.  If more than one new
#       release is found, the release upgrader will attempt to upgrade to
#       the release that immediately succeeds the currently-running
#       release.
#  lts- Check to see if a new LTS release is available.  The upgrader
#       will attempt to upgrade to the first LTS release available after
#       the currently-running one.  Note that this option should not be
#       used if the currently-running release is not itself an LTS
#       release, since in that case the upgrader won&#39;t be able to
#       determine if a newer release is available.
Prompt=normal
</code></pre><p>現在就可以把系統升級到最新服務器版本了，使用下面的命令：</p><pre><code>sudo do-release-upgrade -d
</code></pre><p>按照屏幕上的指示一步一步操作。大功告成！！</p>`,36)),u("p",null,[t[1]||(t[1]=e("已經成功的升級到Ubuntu 13.10了，現在該做些什麼呢？看看我們的新文章“",-1)),a(n,{href:"http://www.unixmen.com/top-things-installing-ubuntu-13-10/"},{default:r(()=>[...t[0]||(t[0]=[e("安裝Ubuntu13.10後最應該做的幾件事",-1)])]),_:1}),t[2]||(t[2]=e("”。現在你的系統已經很完善了。慶祝吧！！",-1))]),t[15]||(t[15]=u("hr",null,null,-1)),u("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://www.unixmen.com/upgrade-ubuntu-13-04-raring-ubuntu-13-10-saucy-salamander/"},{default:r(()=>[...t[3]||(t[3]=[e("http://www.unixmen.com/upgrade-ubuntu-13-04-raring-ubuntu-13-10-saucy-salamander/",-1)])]),_:1})]),u("p",null,[t[7]||(t[7]=e("譯者：",-1)),a(n,{href:"https://github.com/runningwater"},{default:r(()=>[...t[5]||(t[5]=[e("runningwater",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[6]||(t[6]=[e("Caroline",-1)])]),_:1})]),u("p",null,[t[11]||(t[11]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const h=p(i,[["render",g]]);export{T as __pageData,h as default};
